const DICTS: Record<Locale, Dict> = { hy, ru, en };

export function hasTranslation(key: string, locale: Locale = DEFAULT_LOCALE): boolean {
  return Object.hasOwn(DICTS[locale], key);
}

/** Re-translate known interface messages retained in client state. */
export function translateKnownMessage(message: string, locale: Locale): string | undefined {
  const key = Object.keys(en).find((candidate) =>
    LOCALES.some((language) => DICTS[language][candidate] === message),
  );
  return key ? t(key, locale) : undefined;
}

/** Translate a key with optional {param} interpolation. */
export function t<T extends string = string>(
  key: string,
  locale: Locale = DEFAULT_LOCALE,
  params?: Record<string, T | number | string>,
): string {
  const dict = DICTS[locale] ?? DICTS[DEFAULT_LOCALE];
  let value = dict[key] ?? DICTS.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      value = value.replace(new RegExp(`\\{${k}\\}`, "g"), String(v));
    }
  }
  return value;
}

export function isLocale(value: unknown): value is Locale {
  return value === "hy" || value === "ru" || value === "en";
}

// ─────────────────────────────────────────────────────────────────────────────
// useLocale — Zustand-backed hook (re-exported here so consumers import i18n
// from a single module).
//
// NOTE on circular imports: app-store imports DEFAULT_LOCALE from this module,
// and this module imports useAppStore from app-store. To avoid the cycle
// biting at module-eval time, app-store hardcodes the default locale ("hy")
// instead of importing DEFAULT_LOCALE. That keeps i18n → app-store as the
// only direction, which is safe because useAppStore is only invoked inside
// the hook body (at render time, after all modules are evaluated).
// ─────────────────────────────────────────────────────────────────────────────

import { useCallback } from "react";
import { useAppStore } from "@/lib/store/app-store";

export function useLocale() {
  const locale = useAppStore((s: { locale: Locale }) => s.locale);
  const setLocale = useAppStore((s: { setLocale: (l: Locale) => void }) => s.setLocale);
  const translate = useCallback(
    (key: string, params?: Record<string, string | number>) => t(key, locale, params),
    [locale],
  );
  return {
    locale,
    setLocale,
    t: translate,
  };
}
